scripts.pseudorandom_counter:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.find_gcd:
from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    result = reduce(gcd, values)
    return float(result)

scripts.floor_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = sum(a // b for a, b in zip(A, B))
    return float(total)

scripts.look_and_say:
def solve(inputs: dict) -> float:
    N = str(inputs['N'])
    K = inputs['K']

    for _ in range(K):
        result = []
        i = 0
        while i < len(N):
            digit = N[i]
            count = 1
            while i + count < len(N) and N[i + count] == digit:
                count += 1
            result.append(str(count) + digit)
            i += count
        N = ''.join(result)

    return float(N)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

